import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Density of each candidate relative to the best density seen so far among candidates."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    dens = v / np.maximum(w, 1.0)
    best = np.max(dens) if dens.size else 0.0
    if best <= 0.0:
        return np.zeros_like(dens)
    return (dens - best) / best

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Value-to-weight ratio of each candidate, normalised by the max ratio among candidates."""
    r = values / np.maximum(weights, 1)
    return r / (r.max() + 1e-12)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Raw value of each candidate, normalised by the maximum candidate value."""
    return values / (values.max() + 1e-12)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Negative of each candidate's weight normalised by the largest candidate weight."""
    w = np.asarray(weights, dtype=float)
    wmax = w.max() if w.size > 0 else 0.0
    return -(w / (wmax + 1e-12))

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Fraction of remaining capacity that the candidate's weight would consume, signed so heavy items score low and light items score high."""
    w = np.asarray(weights, dtype=float)
    rem = max(float(remaining), 1.0)
    return 1.0 - 2.0 * (w / rem)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """tanh of each candidate's excess (value - weight) divided by the mean absolute excess over candidates."""
    e = values.astype(float) - weights.astype(float)
    s = np.mean(np.abs(e))
    if s < 1e-9:
        s = 1.0
    return np.tanh(e / s)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """If every candidate ends the build (leftover after each is below the min weight of the others), return value / max value; else zeros."""
    v = values.astype(np.float64)
    w = weights.astype(np.float64)
    k = v.shape[0]
    L = remaining - w
    if k == 1:
        m = np.array([np.inf])
    else:
        # all-pairs masked min: min over j != i of w[j]
        big = np.where(np.eye(k, dtype=bool), np.inf, w[None, :])
        m = big.min(axis=1)
    terminal = L < m
    if not np.all(terminal):
        return np.zeros(k)
    return v / max(v.max(), 1e-12)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Density with the denominator shrunk by the mean candidate weight: v / (w + mean(w)), normalised by its max."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    mw = float(w.mean()) if w.size > 0 else 0.0
    if not np.isfinite(mw) or mw <= 0.0:
        mw = 1.0
    s = v / (w + mw)
    mx = float(s.max()) if s.size > 0 else 0.0
    if not np.isfinite(mx) or mx <= 0.0:
        return np.zeros(v.shape[0])
    return s / mx

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Gaussian rank band (top decile by density) times tanh of the value-minus-weight excess."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    k = v.shape[0]
    if k == 0:
        return np.zeros(0)
    d = v / np.maximum(w, 1.0)
    # rank by density descending: r = 0 for the densest
    order = np.argsort(-d, kind="stable")
    r = np.empty(k, dtype=float)
    r[order] = np.arange(k, dtype=float)
    q = max(2.0, 0.1 * k)
    band = np.exp(-((r / q) ** 2))
    e = v - w
    s = np.mean(np.abs(e))
    if s < 1e-9:
        return np.zeros(k)
    return band * np.tanh(e / s)
